fn element_wise_module(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    assert_eq!(arr1.len(), arr2.len(), "Input vectors must have the same length");
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a % b)
        .collect()
}

fn main() {
    let a = vec![10, 25, 100, 7];
    let b = vec![3, 7, 20, 5];
    let result = element_wise_module(&a, &b);
    println!("{:?}", result); // [1, 4, 0, 2]
}